options(stringsAsFactors=FALSE)
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(svglite);library(ragg)})
root <- Sys.getenv("P5_WORK_ROOT")
p <- file.path(root,'P5_MATURE_OLIGODENDROCYTE_PURE_BIOINFO_RESTART')
out <- file.path(p,'MANUSCRIPT_FINAL_POLISH'); src <- file.path(p,'MANUSCRIPT/SUPPLEMENTARY_TABLE_DATA')
figdir <- file.path(out,'FIGURES_FINAL_POLISHED'); panels <- file.path(out,'WORK/PANELS_POLISHED');work<-file.path(out,'WORK')
dir.create(figdir,showWarnings=FALSE);dir.create(panels,showWarnings=FALSE)
read <- function(name) read.delim(file.path(src,paste0(name,'.tsv')),check.names=FALSE,fileEncoding='UTF-8-BOM')
cols <- c(Control='#687F99',TLE='#BD694B',Reference='#687F99')
lineagecols<-c(Astrocytes='#8176A8',Microglia_macrophage='#4C918B')
theme_set(theme_classic(base_size=9,base_family='Arial')+theme(axis.text=element_text(size=8,colour='black'),axis.title=element_text(size=9),plot.title=element_text(size=9,face='bold'),plot.subtitle=element_text(size=8),legend.text=element_text(size=8),legend.title=element_text(size=8),strip.text=element_text(size=8,face='bold'),plot.margin=margin(7,8,7,8),legend.key.height=grid::unit(3,'mm')))
saveplot<-function(g,name,w=183,h=160,dir=figdir){
 f<-file.path(dir,name)
 grDevices::cairo_pdf(paste0(f,'.pdf'),width=w/25.4,height=h/25.4,family='Arial',bg='white');print(g);dev.off()
 svglite::svglite(paste0(f,'.svg'),width=w/25.4,height=h/25.4,bg='white');print(g);dev.off()
 ggsave(paste0(f,'.png'),g,width=w,height=h,units='mm',dpi=600,device=agg_png,bg='white')
 if(dir==figdir)ggsave(file.path(work,paste0(name,'_preview.png')),g,width=w,height=h,units='mm',dpi=300,device=agg_png,bg='white')
}
tagged<-function(g,tag)g+labs(tag=tag)+theme(plot.tag=element_text(size=10,face='bold'),plot.tag.position=c(0,1))
schematic<-function(labels,note){
 d<-data.frame(x=seq_along(labels),y=1,label=labels)
 ggplot(d,aes(x,y))+geom_segment(data=data.frame(x=head(d$x,-1)+.20,xend=tail(d$x,-1)-.20,y=1,yend=1),aes(x=x,xend=xend,y=y,yend=yend),inherit.aes=FALSE,linewidth=.4,arrow=grid::arrow(length=grid::unit(1.5,'mm')))+geom_label(aes(label=label),size=3.0,family='Arial',label.size=.25,fill='white',label.padding=grid::unit(2.0,'mm'))+coord_cartesian(xlim=c(.65,length(labels)+.35),ylim=c(.3,1.65),clip='off')+theme_void(base_family='Arial')+labs(caption=note)+theme(plot.caption=element_text(size=8,hjust=.5),plot.margin=margin(8,8,8,8))
}
donorplot<-function(d,y,label){
 d$group<-factor(d$group,levels=c('Control','Reference','TLE'))
 ggplot(d,aes(group,.data[[y]],colour=group))+stat_summary(fun=median,geom='point',shape=95,size=10,colour='black')+stat_summary(fun.min=function(z)quantile(z,.25),fun.max=function(z)quantile(z,.75),geom='errorbar',width=.12,colour='black',linewidth=.45)+geom_point(position=position_jitter(width=.065,height=0,seed=11),size=2.4)+scale_colour_manual(values=cols,guide='none')+labs(x=NULL,y=label)+theme(axis.text.x=element_text(size=9))
}
full<-read('S2_full_spectrum');top<-read('S2_Top100');effects<-read('S3_P5_effects');usage<-read('S3_P5_donor_usage')
r<-cor(full$primary_score,full$sensitivity_score);stopifnot(abs(r-.932685511442094)<1e-10)
A<-schematic(c('GSE190452\n4 TLE + 4 Control','Mature\noligodendrocytes','Donor-balanced\nprimary + sensitivity','cNMF\nK = 6','P5 program'), '450 OL nuclei/donor/input; 3,600 nuclei/input\nDonor-level disease association + robustness')
ann<-full[match(c('PLP1','CRYAB','SCD','CNP','ERMN'),full$gene),];ann$lx<-ann$primary_score+c(-.00055,-.0002,-.0005,-.00055,-.0006);ann$ly<-ann$sensitivity_score+c(.00040,.00045,-.00042,.00045,-.0003)
B<-ggplot(full,aes(primary_score,sensitivity_score))+geom_point(size=.25,alpha=.18,colour='#707A82')+geom_segment(data=ann,aes(xend=lx,yend=ly),linewidth=.2)+geom_text(data=ann,aes(x=lx,y=ly,label=gene),size=2.8,hjust=.5)+labs(x='Primary P5 spectrum score',y='Sensitivity P5 spectrum score',title='Gene-spectrum concordance',subtitle=sprintf('Pearson r = %.6f\nGene points are not biological replicates',r))
du<-usage[usage$sampling=='primary',];du$group<-ifelse(du$condition=='Normal','Control','TLE')
C<-donorplot(du,'clr_usage','P5 CLR usage')+labs(title='Eight biological donors',subtitle='One point per donor; median and IQR')
effects$scheme<-factor(effects$sampling,levels=c('sensitivity','primary'))
D<-ggplot(effects,aes(effect_TLE_minus_Normal,scheme))+geom_vline(xintercept=0,colour='#BBBBBB')+geom_point(size=3,colour=cols['TLE'])+geom_text(aes(label=paste0(sprintf('effect = %.5f; g = %.5f; exact P = %.7f',effect_TLE_minus_Normal,hedges_g,exact_p_value),ifelse(sampling=='primary','; FDR = 0.60',''))),x=.02,nudge_y=.25,hjust=0,size=2.8)+scale_y_discrete(labels=c('Sensitivity','Primary'))+coord_cartesian(xlim=c(-.04,2.25),clip='off')+labs(x='TLE − Control effect (CLR units)',y=NULL,title='Point effect estimates',subtitle='Points show effects; no confidence intervals displayed.\nLODO sign stability = 1.00 for both',caption='Primary FDR = 0.60\nP5 did not pass the adjusted discovery threshold.')+theme(plot.caption=element_text(size=9,face='bold',hjust=0))
f1<-tagged(A,'A')/(tagged(B,'B')|tagged(C,'C'))/tagged(D,'D')+plot_layout(heights=c(.8,2,1.4))
invisible(NULL)

ext<-read('S5_donor_scores');ext<-ext[ext$compartment=='Mature_oligodendrocyte' & ext$donor_id%in%c('14431','19619','20188','H18.30.002','H19.30.001','H19.30.002'),]
ext$group<-ifelse(ext$group=='TLE','TLE','Reference')
ranking<-read('S5_six_program_specificity');contrib<-read('S5_gene_contributions')
dif<-ranking$mean_difference[ranking$program=='Oligodendrocytes__P5'|ranking$program=='P5'];if(!length(dif))dif<-ranking$mean_difference[grepl('P5$',ranking$program)]
stopifnot(abs(mean(ext$raw_weighted_rank_score[ext$group=='TLE'])-mean(ext$raw_weighted_rank_score[ext$group=='Reference'])-dif)<1e-8)
A<-ggplot(data.frame(x=c(1,2),y=1,label=c('GSE140393 TLE\n3 adult donors\nSurgical whole-cell OL','SEA-AD reference\n3 adult MTG donors\nNuclei')),aes(x,y,label=label))+geom_label(size=3,family='Arial',label.size=.25,fill='white',label.padding=grid::unit(2,'mm'))+annotate('text',x=1.5,y=1,label='vs',family='Arial',size=3)+annotate('text',x=1.5,y=.3,label='Cross-dataset contextual comparison',family='Arial',size=2.8)+coord_cartesian(xlim=c(.6,2.4),ylim=c(.1,1.7),clip='off')+theme_void(base_family='Arial')+labs(caption='NOT anatomically matched replication')+theme(plot.caption=element_text(size=8,hjust=.5),plot.margin=margin(8,8,8,8))
B<-donorplot(ext,'raw_weighted_rank_score','Raw weighted P5 rank score')+scale_x_discrete(labels=c(Reference='SEA-AD\nreference',TLE='GSE140393\nTLE'))+labs(title='Adult mature oligodendrocytes',subtitle='Three donors per dataset; 93 mapped P5 genes\nZoomed y-axis')
ranking$isP5<-grepl('P5$',ranking$program)
C<-ggplot(ranking,aes(mean_difference,reorder(sub('Oligodendrocytes__','',program),mean_difference),fill=isP5))+geom_col(width=.6)+geom_vline(xintercept=0,colour='black',linewidth=.3)+scale_fill_manual(values=c('FALSE'='#B5BEC6','TRUE'='#BD694B'),guide='none')+labs(x='Signed GSE140393 TLE − SEA-AD reference\nrank-score effect',y=NULL,title='Six-program effect ranking',subtitle='P5: difference = 0.0677906; Hedges g = 4.44699\nExact P = 0.10\nMinimum possible two-sided exact P for 3 vs 3 = 0.10')
share<-data.frame(category=c('Major myelin genes','Top 10 P5 weight genes'),pct=c(sum(contrib$weighted_contribution[tolower(contrib$major_myelin_gene)=='true'])/dif,sum(contrib$weighted_contribution[tolower(contrib$top10_weight_gene)=='true'])/dif)*100)
stopifnot(abs(share$pct[1]-1.53)<.02,abs(share$pct[2]-9.40)<.02)
D<-ggplot(share,aes(pct,category))+geom_col(width=.5,fill='#4C918B')+geom_text(aes(label=sprintf('%.2f%%',pct)),hjust=-.15,size=3.1)+coord_cartesian(xlim=c(0,14))+labs(x='Contribution to signed net difference (%)',y=NULL,title='Gene contributions and sensitivity',subtitle='Overlapping categories; not a partition',caption='Cell-number / UMI resampling:\n100/100 resamples retained a positive\neffect direction in each analysis\nDetailed sensitivity results: Fig. S1')+theme(plot.caption=element_text(size=8,hjust=0))
f2<-(tagged(A,'A')|tagged(B,'B'))/(tagged(C,'C')|tagged(D,'D'))
invisible(NULL)

catcols<-c(Myelin='#687F99','Lysosome/proteostasis'='#4C918B',Lipid='#BD9A4E',Other='#A0A0A0')
genes<-c('PLP1','CRYAB','SCD','CNP','ERMN','MAG','LAMP2','APOE','LAMP1','PSAP')
tg<-top[match(genes,top$gene),];stopifnot(!anyNA(tg$gene))
tg$category<-c('Myelin','Lysosome/proteostasis','Lipid','Myelin','Myelin','Myelin','Lysosome/proteostasis','Lipid','Lysosome/proteostasis','Lysosome/proteostasis')
tg$label<-paste0(tg$gene,'  (#',tg$spectrum_rank,')');tg$label<-factor(tg$label,levels=rev(tg$label))
A<-ggplot(tg,aes(meta_program_score,label,colour=category))+geom_segment(aes(x=0,xend=meta_program_score,yend=label),linewidth=.6)+geom_point(size=2.6)+scale_colour_manual(values=catcols)+labs(x='P5 meta-spectrum score',y=NULL,title='Selected ranked P5 features')+theme(legend.position='bottom',legend.title=element_blank(),legend.text=element_text(size=8))+guides(colour=guide_legend(nrow=2))
path<-read('S4_P5_general_pathways');terms<-c('central nervous system myelination','Chaperone Mediated Autophagy','lysosomal transport','lipid transport')
sel<-do.call(rbind,lapply(terms,function(t){z<-path[grepl(t,path$term_name,ignore.case=TRUE,fixed=TRUE),];if(!nrow(z))stop(paste('Missing pathway',t));z[which.min(z$adjusted_p_value),]}))
stopifnot(identical(as.numeric(sel$intersection_size),c(5,4,6,2)))
write.table(sel,file.path(work,'Figure3B_original_selected_rows.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
sel$label<-factor(c('CNS myelination','Chaperone-mediated\nautophagy','Lysosomal transport','Positive regulation of\nphospholipid transport'),levels=rev(c('CNS myelination','Chaperone-mediated\nautophagy','Lysosomal transport','Positive regulation of\nphospholipid transport')))
B<-ggplot(sel,aes(-log10(adjusted_p_value),label,size=intersection_size))+geom_point(colour='#4C918B')+scale_size_continuous(range=c(2,5),breaks=c(2,4,5,6))+labs(x='−log₁₀(adjusted P)',y=NULL,size='Gene overlap',title='GO and Reactome annotations')+theme(legend.position='bottom')
over<-read('S4_26E_overlap')
chosen<-c('Lysosome_autophagy_proteostasis','Lysosome_autophagy_proteostasis_deconfounded','Phagolysosome_lipid_processing','FRIDMAN_SENESCENCE_UP','SAUL_SEN_MAYO','REACTOME_CELLULAR_SENESCENCE','REACTOME_SENESCENCE_ASSOCIATED_SECRETORY_PHENOTYPE_SASP','Stable_cell_cycle_exit','DDR_genome_instability')
labels<-c('Lysosome/proteostasis','Lysosome (deconf.)','Phagolysosome/lipid','Fridman','SenMayo','Reactome senescence','SASP','Cell-cycle exit','DNA damage')
ov<-over[match(chosen,over$program),];ov$label<-factor(labels,levels=rev(labels))
genes2<-c('LAMP1','LAMP2','APOE','SPP1','CRYAB','HSPA2','RHOB','CD9','UBB')
mat<-expand.grid(gene=genes2,label=labels);mat$overlap<-mapply(function(g,l)g%in%strsplit(ov$overlap_genes[match(l,labels)],';',fixed=TRUE)[[1]],mat$gene,mat$label)
mat$label<-factor(mat$label,levels=rev(labels));mat$gene<-factor(mat$gene,levels=genes2)
C<-ggplot(mat,aes(gene,label,fill=overlap))+geom_tile(colour='white',linewidth=.5)+scale_fill_manual(values=c('FALSE'='#F1F2F3','TRUE'='#4C918B'),labels=c('No overlap','Top-100 overlap'))+labs(x=NULL,y=NULL,title='Selected functional-set overlaps',subtitle='Full 26-signature results: Table S4')+theme(axis.text.x=element_text(angle=45,hjust=1),legend.position='bottom',legend.title=element_blank())
sen<-ov[4:9,];sen$gene_label<-ifelse(sen$overlap_k==0,'0 overlap',sen$overlap_genes)
D<-ggplot(sen,aes(overlap_k,label))+geom_segment(aes(x=0,xend=overlap_k,yend=label),colour='#B0B0B0')+geom_point(size=2.6,colour='#8176A8')+geom_text(aes(label=paste0(gsub(';',' / ',gene_label),'\nFDR = ',formatC(FDR_26E,digits=5,format='f'))),x=3.4,hjust=0,size=2.8)+scale_x_continuous(breaks=0:3)+coord_cartesian(xlim=c(0,9.5),clip='on')+labs(x='Top-100 overlap count',y=NULL,title='Senescence evidence comparison')
f3<-(tagged(A,'A')|tagged(B,'B'))/(tagged(C,'C')|tagged(D,'D'))+plot_annotation(caption='Predominant myelin–lysosome/proteostasis remodeling\nPartial senescence-associated overlap does not establish canonical senescence.',theme=theme(plot.caption=element_text(size=8.5,hjust=.5)))
saveplot(f3,'Figure3',h=185)
for(nm in c('A','B','C','D'))saveplot(get(nm),paste0('Fig3',nm),w=95,h=85,dir=panels)
